#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Generate the single Phase1H audit report after analysis and figure review."""
from pathlib import Path
import json
import pandas as pd
ROOT=Path(__file__).resolve().parents[1];O=ROOT/'results/phase1h';P=ROOT/'reports/PHASE1H_DONOR_FOLD_STABILITY_AUDIT.md'
def read(n):return pd.read_csv(O/n,sep='\t')
def table(df):
 def fmt(v):
  if isinstance(v,float):return f'{v:.4f}'
  return str(v)
 cols=list(df.columns);out=['| '+' | '.join(cols)+' |','| '+' | '.join(['---']*len(cols))+' |']
 out.extend('| '+' | '.join(fmt(v) for v in row)+' |' for row in df.itertuples(index=False,name=None));return '\n'.join(out)
def names(items):return ', '.join(items) if len(items) else 'None'
def link(n):return f'[{n}](<{O/n}>)'
def main():
 if P.exists():raise RuntimeError('Existing report must be inspected and evidence preserved before an update')
 verdict=json.loads((O/'verdict.json').read_text());qa=json.loads((O/'verification.json').read_text());assert qa['all_required_checks_pass'] and qa['visual_review_complete']
 cl=read('target_stability_classification.tsv');ss=read('repeated_fold_stability.tsv');loo=read('leave_one_donor_out_influence.tsv');full=read('full_frozen_metrics.tsv');assoc=read('support_error_association.tsv');joint=read('low_variance_influence_cooccurrence.tsv');invalid=read('invalid_partitions.tsv');v=verdict.copy()
 pending=v.get('verdict') is None
 if pending:v['verdict']='PENDING HUMAN CLASSIFICATION — draft, no final stage verdict assigned'
 def sign(t,k):return f"{cl.set_index('target').loc[t,k]*100:.1f}%"
 ts=cl.target.tolist()
 vals=[('PHASE 1H VERDICT',v['verdict']),('Primary targets audited','3'),('Independent donors','19'),('Leave-one-donor analyses completed','19/19'),('Repeated donor partitions','50 pre-registered seeds; POOLED and PF_ONLY; '+str(len(invalid))+' invalid target/stratum partitions'),('Original frozen fold retained','YES'),('Any donor removed from primary cohort','NO'),('Epithelial injury DeltaR2 sign stability',sign(ts[0],'delta_sign_stability')),('Fibroblast activation DeltaR2 sign stability',sign(ts[1],'delta_sign_stability')),('Macrophage inflammatory DeltaR2 sign stability',sign(ts[2],'delta_sign_stability')),('Epithelial residual sign stability',sign(ts[0],'residual_sign_stability')),('Fibroblast residual sign stability',sign(ts[1],'residual_sign_stability')),('Macrophage residual sign stability',sign(ts[2],'residual_sign_stability')),('Highest-leverage donor',v['highest_leverage_donor']),('Number of extreme-leverage donors',str(v['n_extreme_donors'])),('M2 extrapolation association','; '.join(f'{r.target}: rho={r.donor_support_Spearman:.3f}, p={r.donor_support_p:.4f}' for r in cl.itertuples())),('Original fold extreme','YES' if cl.original_fold_extreme.any() else 'NO'),('Targets classified STABLE_SIGNAL',names(cl[cl.classification.eq('STABLE_SIGNAL')].target.tolist())),('Targets classified STABLE_NULL',names(cl[cl.classification.eq('STABLE_NULL')].target.tolist())),('Targets classified M2_EXTRAPOLATION_DRIVEN',names(cl[cl.classification.eq('M2_EXTRAPOLATION_DRIVEN')].target.tolist())),('Targets classified DONOR_LEVERAGE_DRIVEN',names(cl[cl.classification.eq('DONOR_LEVERAGE_DRIVEN')].target.tolist())),('Targets classified FOLD_INSTABILITY',names(cl[cl.classification.eq('FOLD_INSTABILITY')].target.tolist())),('External validation authorized',v['external_validation_authorized']),('Recommended next phase',v['next_phase'])]
 lines=[f'{i}. **{label}:** {value}' for i,(label,value) in enumerate(vals,1)]
 if pending:
  lines += ['', '## Human decision required — report draft', '', 'All numerical analyses and figure QA are complete. Final classification is pending because the prospectively specified categories do not cover the observed combination. POOLED delta sign consistency is 98%, 100% and 92%; residual consistency is 84%, 98% and 88%, respectively. Yet deleting donors changes the target CI/FDR interpretation in 5, 13 and 18 cases. None of the 19 deletions changes the original global Phase1 verdict. The primary support criteria are not met, and original fold percentiles are not extreme.', '', 'The targets fail the no-single-donor-interpretation-change criterion for STABLE_SIGNAL; more than two donors trigger interpretation changes, so DONOR_LEVERAGE_DRIVEN is not established; all repeat sign consistency values exceed 80%, so frequent-sign-flip FOLD_INSTABILITY is not established. Effects are not near zero, excluding STABLE_NULL. Assigning HOLD_FOLD_INSTABILITY through a generic fallback would contradict the supplied criteria; that fallback was removed without changing any model, result or prospective threshold.', '', 'A human-authorized clarification or additional verdict category is required. Proposed descriptive category: HOLD_INFERENCE_INSTABILITY, meaning numerically consistent partition directions with donor-sensitive confidence/FDR inference; EXTERNAL VALIDATION AUTHORIZED remains NO. This proposed category is not yet authorized or assigned. Evidence is preserved for review; no reruns or exclusions are required.']
 lines+=['','## Scope and frozen analysis','', 'This diagnostic audit retains all 19 donors in the original primary analysis. The common universe contains 12,144 regions; epithelial injury, fibroblast activation and macrophage inflammatory retain 3,219, 4,869 and 2,661 eligible regions, respectively. The original predictions, frozen five donor folds, three targets, lineage threshold of 20 cells, 150 µm scale, C/N ontology, covariates, CPU Phikon-v2 embeddings and Ridge model family remain unchanged.','', 'The primary influence/support audit uses the disease-adjusted analysis. Repeated partition stability uses POOLED, with independently retrained PF_ONLY as the companion analysis. These strata answer different questions: POOLED partition reproducibility does not replace the disease-adjusted primary effect or its three-target FDR family.','', 'Each donor deletion refits the complete frozen model ladder, all pre-existing shortcut arms and the residual pipeline in POOLED, PF_ONLY and DISEASE_ADJUSTED. Removing a control donor from PF_ONLY is structurally inapplicable and retains the identical PF_ONLY result. Deletion is diagnostic only. Original Macenko embeddings are held fixed as authorized scientific inputs; the audit is conditional on these existing original-fold references, not a new stain-reference extraction experiment. Repeated partitions use RAW X only and do not reuse a new fold as a Macenko reference.','', 'Ridge tuning uses donor-grouped training-only inner CV over the original 19 log-spaced alphas from 10^-4 to 10^5. Donor-equal feature standardization, target centering and weighting match the original pipeline. The residual target is generated by a second donor cross-fit entirely inside each outer training set; its own Ridge tuning also uses training donors only. Held-out donor outcomes never enter training residual construction. Negative R² values are retained.','', 'Uncertainty uses the original 2,000 donor-cluster bootstrap replicates of complete OOF predictions, with fixed original bootstrap seed conventions. Paired ΔR² uses the same bootstrap donor draws for M2 and M4. Bootstrap intervals are conditional on fitted OOF models; the repeated partitions measure partition variability, not independent-cohort replication. Three-target BH values within each LOO diagnostic stratum support influence classification; only disease-adjusted BH remains the original primary inferential family.','', 'All 50 seeds, 1001–1050, and operational thresholds were written before Phase1H computation. Within each disease, shuffled donors are assigned cyclically to five folds with a seeded offset. No outcome, image result or performance is used to balance or select partitions. Invalid partitions are recorded without replacement.','', 'M2 support uses only C+N+frozen Z and training donors. Training-only donor-equal scaling precedes regularized Ledoit–Wolf Mahalanobis distance. Covariance estimation is region-equal and diagnostic; it does not alter donor-equal Ridge fitting. Nearest-neighbor distance uses standardized Euclidean distance to a different training donor; training reference distances also exclude the same donor, avoiding self-distance zero. Both train-derived 95th/99th percentile cutoffs are reported. A convex hull is impractical in 32/33 dimensions; the exact nearest-neighbor support cloud is the reported cloud-distance proxy.','', 'A donor is unsupported when at least 10% of its regions exceed the training Mahalanobis 99th percentile. Strong support/error association requires donor Spearman rho≥0.5 and nominal p<0.05. Extrapolation-driven classification additionally requires at least 50% of positive paired SSE gain in unsupported donors and at least one such donor deletion reducing ΔR² by ≥50% of the full effect. Region-level correlations are exploratory and do not determine the verdict.','', 'EXTREME leverage marks a delta/residual sign change or prospective qualitative CI/FDR interpretation change. HIGH leverage marks the upper 10% of absolute delta influence or ≥50% relative change. MODERATE is at/above the median absolute influence after the preceding categories; remaining donors are LOW. Low target variance means the bottom 10% within target/stratum. No flag triggers exclusion. The paired error cases use per-model donor MAE above the 75th percentile as bad and an M4 MAE reduction of ≥25% as much better.','', 'Sign stability is the larger positive/negative partition fraction: HIGH≥80%, MODERATE65–79%, LOW<65%. Direction and fractions are also reported to distinguish a stable harmful effect from a positive signal. STABLE_NULL requires both repeated 5–95% intervals inside ±0.02, both median absolute effects≤0.01, original bootstrap intervals inside ±0.05 and maximum LOO absolute influences≤0.02. External validation is authorized by this decision logic only for a positive stable delta and positive stable residual target; no external analysis is executed here.','', '## Target-specific summaries','']
 for r in cl.itertuples():
  b=full[full.target.eq(r.target)&full.stratum.eq('DISEASE_ADJUSTED')].iloc[0]
  lines += ['### '+r.target.replace('_',' '),'',f'Full disease-adjusted ΔR²={r.full_DeltaR2:.4f}; donor-bootstrap 95% CI [{b.delta_CI_low:.4f}, {b.delta_CI_high:.4f}]. The LOO range is [{r.loo_DeltaR2_min:.4f}, {r.loo_DeltaR2_max:.4f}], with {r.delta_sign_flips} delta sign flips, {r.residual_sign_flips} residual sign flips and {r.interpretation_flips} CI/FDR interpretation changes. The highest absolute delta influence belongs to {r.highest_leverage_donor}.','',f'POOLED repeated median ΔR²={r.median_DeltaR2:.4f}, 5–95% range [{r.DeltaR2_p5:.4f}, {r.DeltaR2_p95:.4f}]. Delta sign stability={r.delta_sign_stability:.1%}; residual sign stability={r.residual_sign_stability:.1%}; median residual R²={r.median_residual_R2:.4f}. The original POOLED delta is at percentile {r.original_fold_percentile:.1f}; original-fold extreme={r.original_fold_extreme}.','',f'Donor-level M2 support/error Spearman rho={r.donor_support_Spearman:.3f}, nominal p={r.donor_support_p:.4f}. Unsupported donors account for {r.unsupported_positive_gain_fraction:.1%} of positive paired SSE gain. Final target classification: **{r.classification}**.','']
 lines+=['## Table H1 — Donor influence','',table(loo[loo.stratum.eq('DISEASE_ADJUSTED')][['target','donor_id','full_DeltaR2','loo_DeltaR2','delta_influence','full_residual_R2','loo_residual_R2','residual_influence','delta_sign_flip','residual_sign_flip','classification_change','leverage_category']]),'', 'Complete M2/M4, correlation, CI and FDR fields across all strata: '+link('tableH1_donor_influence.tsv'),'', '## Table H2 — M2 support / extrapolation','',table(read('m2_support_distance.tsv').query("stratum == 'DISEASE_ADJUSTED'")[['target','donor_id','mahalanobis_median','mahalanobis_fraction_outside95','mahalanobis_fraction_outside99','nearest_neighbor_median','C_fraction_regions_ge1','N_fraction_regions_ge1']]),'', 'All distance percentiles and composition/neighborhood unsupported feature/region fractions: '+link('tableH2_m2_support.tsv'),'', '## Table H3 — Repeated-fold stability','',table(ss[['target','stratum','n_partitions','median_DeltaR2','DeltaR2_IQR','DeltaR2_p5','DeltaR2_p95','delta_fraction_positive','delta_fraction_negative','median_residual_R2','residual_p5','residual_p95','residual_fraction_positive','delta_sign_stability','residual_sign_stability','original_fold_percentile']]),'', 'Complete six mandatory metrics and variability summaries: '+link('tableH3_repeated_stability.tsv'),'', '## Table H4 — Target classification','',table(cl[['target','classification','interpretation_flips','original_fold_extreme','positive_signal','extrapolation_criteria']]),'',link('tableH4_target_classification.tsv'),'', '## Low variance and paired error diagnostics','',table(joint[joint.stratum.eq('DISEASE_ADJUSTED')&joint.LOW_TARGET_VARIANCE][['target','donor_id','target_variance','M2_R2','extreme_M2_R2','extreme_delta_influence','extreme_residual_influence','leverage_category']]),'', 'Low-variance flags remain descriptive. '+link('donor_error_profile.tsv')+' reports donor target moments, M2/M4 RMSE and MAE, absolute residuals, paired error improvement and residual-model error. '+link('m2_m4_paired_leverage.tsv')+' identifies hard donors, possible morphology rescue, incremental signal and generalization harm under the prospective thresholds. '+link('high_leverage_frozen_metadata.tsv')+' retains existing disease/TMA/run/LF-MF/section/region counts and C/N distribution quantiles only. No new clinical or pathology annotation was added.','', '## Figures and visual QA','']
 figs=[('H1_leave_one_donor_influence','H1 | Donor deletion influence','Three targets; all 19 diagnostic deletions; disease-adjusted delta minus full delta. Marks are deterministic refits, so no invented error bars are added. Red marks indicate extreme leverage, with category also available in Table H1.'),('H2_m2_support_donor_error','H2 | M2 support distance and donor error','Three targets; 19 independent donor points per panel. X is median training-derived regularized Mahalanobis distance; Y is frozen OOF M2 MAE. Associations use donor-level Spearman with no multiplicity-adjusted evidential claim.'),('H3_repeated_fold_delta','H3 | Repeated-partition morphology increment','Three targets; 50 seeds in each of POOLED and PF_ONLY. All partitions are drawn; center=median, thick segment=IQR, whiskers=5–95% partition range. Open diamonds show original frozen folds; zero is the no-increment reference.'),('H4_repeated_fold_residual','H4 | Repeated-partition residual prediction','Same six target/stratum partitions and variability definition as H3; residual R² uses training-side donor cross-fit residuals. Negative values are preserved.'),('H5_paired_m2_m4_error','H5 | Paired donor M2/M4 errors','Three targets; all 19 donor pairs; disease-adjusted OOF MAE. Identity line separates improved M4 generalization below the line from worsening above. Two largest M4 errors are labeled without excluding other points.')]
 for n,title,caption in figs:lines += ['### '+title,'',f'![{title}](<{O/"figures"/(n+".png")}>)','',caption+' Editable vector: '+f'[{n}.svg](<{O/"figures"/(n+".svg")}>)','']
 lines+=['All figures use Python, editable Arial SVG text, 183 mm width and 300 dpi PNG previews. Five-point typography floor and all 15 panels were inspected. Sources use all requested donors/partitions; jitter is deterministic display spacing only. No image extraction, image contrast adjustment or simulated observation is used. PDF export/text auditing is omitted under the user’s no-automatic-PDF policy; SVG rendered font sizes are audited instead. Generic source-validator warnings and the PDF export policy exception are recorded in '+link('figure_source_validation.json')+' and '+link('verification.json')+'.','', '## Verification and interpretation boundaries','',table(pd.DataFrame([{'check':k,'pass':value} for k,value in qa['checks'].items()])), '', 'Original scientific inputs and primary predictions are unchanged. For each LOO refit, the original held-out fold that contains the removed donor has identical training donors; predictions on its remaining test donors are checked against original M2/M4/residual predictions. All selected alphas remain on the frozen grid. Training/test donor overlap is zero, and every training-side cross-fit record is contained in the relevant outer training donors.','', 'The support criteria are operational diagnostics. Observational associations cannot establish a causal source of M2 failure. Fifty partitions reuse the same 19 donors; repeated sign consistency does not establish transportability. Diagnostic deletion results do not authorize donor removal, a restricted primary cohort or performance-selected folds. Optional coefficient stability analysis was not run.','', '```text\nDONORS_EXCLUDED_POSTHOC = NO\nFOLDS_SELECTED_BY_PERFORMANCE = NO\nTARGETS_CHANGED = NO\nENCODER_CHANGED = NO\nCOMMON_UNIVERSE_CHANGED = NO\nMODEL_FAMILY_CHANGED = NO\nOUTCOME_USED_TO_DEFINE_SUPPORT = NO\n```','', 'Actual original Phase1 verdict changes are separately recomputed with its frozen complete decision logic, including composition intervals, shortcut arms and donor heterogeneity: '+link('loo_original_phase1_verdict.tsv')+'. Target CI/FDR interpretation flags remain distinct from a change in the global stage verdict.', '', '## Stop','', '**PHASE 1H VERDICT:** '+v['verdict'], '**EXTERNAL VALIDATION AUTHORIZED = '+v['external_validation_authorized']+'**', '', ('Numerical Phase1H audit and figure QA are complete; final classification and report sign-off await a human decision.' if pending else 'Phase1H is complete.')+' No external cohort search, download, validation, encoder change, target expansion or manuscript expansion has begun. Await a separate human decision.']
 P.write_text('\n'.join(lines)+'\n');print(P)
if __name__=='__main__':main()
